"""One-time migration of existing Shubhvastra SQLite data to PostgreSQL.
Usage: DATABASE_URL='postgresql+psycopg://...' python migrate_sqlite_to_postgres.py --source party_reporting.db
This intentionally refuses to overwrite a PostgreSQL database that already contains business rows.
"""
import argparse, os, sqlite3, sys
from sqlalchemy import create_engine, text
from werkzeug.security import generate_password_hash

TABLES = ["agents", "parties", "orders", "order_items", "order_item_sizes", "order_dispatches", "sku_master"]
DDL = [
"CREATE TABLE IF NOT EXISTS agents (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_name VARCHAR(200) NOT NULL UNIQUE, phone_number VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS parties (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, party_name VARCHAR(250) NOT NULL, phone_number VARCHAR(100) NOT NULL, address TEXT NOT NULL DEFAULT '', city VARCHAR(150) NOT NULL DEFAULT '', state VARCHAR(150) NOT NULL DEFAULT '', gst_number VARCHAR(100) NOT NULL DEFAULT '', reference VARCHAR(30) NOT NULL DEFAULT 'DIRECT', transport_details TEXT NOT NULL DEFAULT '', transport_gst_number VARCHAR(100) NOT NULL DEFAULT '', agent_id INTEGER NULL REFERENCES agents(id) ON DELETE RESTRICT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS orders (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_no INTEGER NOT NULL UNIQUE, order_date DATE NOT NULL, party_id INTEGER NOT NULL REFERENCES parties(id) ON DELETE RESTRICT, packaging TEXT NOT NULL DEFAULT '[]', narration TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, cancelled INTEGER NOT NULL DEFAULT 0)",
"CREATE TABLE IF NOT EXISTS order_items (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, sr_no INTEGER NOT NULL, particulars VARCHAR(250) NOT NULL, piece_rate NUMERIC(12,2) NOT NULL DEFAULT 0, discount NUMERIC(12,2) NOT NULL DEFAULT 0)",
"CREATE TABLE IF NOT EXISTS order_item_sizes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_item_id INTEGER NOT NULL REFERENCES order_items(id) ON DELETE CASCADE, size_code VARCHAR(10) NOT NULL, ordered_qty INTEGER NOT NULL CHECK(ordered_qty > 0), cancelled INTEGER NOT NULL DEFAULT 0, UNIQUE(order_item_id,size_code))",
"CREATE TABLE IF NOT EXISTS order_dispatches (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_size_id INTEGER NOT NULL REFERENCES order_item_sizes(id) ON DELETE RESTRICT, dispatched_size VARCHAR(10) NOT NULL, qty INTEGER NOT NULL CHECK(qty > 0), dispatch_date DATE NOT NULL, details TEXT NOT NULL DEFAULT '', invoice_number VARCHAR(150) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS sku_master (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku_number VARCHAR(250) NOT NULL UNIQUE, sale_rate NUMERIC(12,2) NOT NULL CHECK(sale_rate >= 0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'staff', active INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)"
]

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--source',default='party_reporting.db')
    ap.add_argument('--admin-user',default=os.getenv('SHUBHVASTRA_ADMIN_USER','admin'))
    ap.add_argument('--admin-password',default=os.getenv('SHUBHVASTRA_ADMIN_PASSWORD',''))
    args=ap.parse_args()
    url=os.getenv('DATABASE_URL','').strip()
    if not url: sys.exit('ERROR: Set DATABASE_URL to your PostgreSQL connection string first.')
    if url.startswith('postgres://'): url=url.replace('postgres://','postgresql+psycopg://',1)
    elif url.startswith('postgresql://') and '+psycopg' not in url: url=url.replace('postgresql://','postgresql+psycopg://',1)
    if not os.path.isfile(args.source): sys.exit(f'ERROR: SQLite source file not found: {args.source}')
    src=sqlite3.connect(args.source); src.row_factory=sqlite3.Row
    dst=create_engine(url,pool_pre_ping=True)
    try:
        with dst.begin() as conn:
            for ddl in DDL: conn.execute(text(ddl))
            counts={t:int(conn.execute(text(f'SELECT COUNT(*) FROM {t}')).scalar_one()) for t in TABLES}
            if any(counts.values()):
                sys.exit('ERROR: Target PostgreSQL already has business data. Migration stopped to avoid duplicates/overwrite. Use a fresh empty database.')
            for table in TABLES:
                cols=[r['name'] for r in src.execute(f'PRAGMA table_info({table})').fetchall()]
                if not cols: continue
                rows=src.execute(f'SELECT * FROM "{table}"').fetchall()
                if not rows: continue
                # Add missing columns introduced by newer web schema without changing original records.
                if table=='orders' and 'cancelled' not in cols: cols.append('cancelled')
                if table=='order_item_sizes' and 'cancelled' not in cols: cols.append('cancelled')
                if table=='order_dispatches' and 'invoice_number' not in cols: cols.append('invoice_number')
                orig_cols=[r['name'] for r in src.execute(f'PRAGMA table_info({table})').fetchall()]
                insert_cols=orig_cols.copy()
                extra={}
                if table=='orders' and 'cancelled' not in orig_cols: insert_cols.append('cancelled'); extra['cancelled']=0
                if table=='order_item_sizes' and 'cancelled' not in orig_cols: insert_cols.append('cancelled'); extra['cancelled']=0
                if table=='order_dispatches' and 'invoice_number' not in orig_cols: insert_cols.append('invoice_number'); extra['invoice_number']=''
                bindnames=[f'v{i}' for i in range(len(insert_cols))]
                sql=f"INSERT INTO {table} ({','.join(insert_cols)}) VALUES ({','.join(':'+x for x in bindnames)})"
                for row in rows:
                    vals=dict(row); vals.update(extra)
                    params={b:vals[c] for b,c in zip(bindnames,insert_cols)}
                    if table=='orders' and isinstance(params.get('v2'),str): pass
                    conn.execute(text(sql),params)
            # Ensure next generated IDs continue after migrated IDs.
            for table in TABLES:
                conn.execute(text(f"SELECT setval(pg_get_serial_sequence('{table}','id'), GREATEST(COALESCE((SELECT MAX(id) FROM {table}),1),1), COALESCE((SELECT MAX(id) FROM {table}),0)>0)"))
            password=args.admin_password
            if not password:
                print('WARNING: No admin password provided. Create an admin password in Streamlit secrets before first app launch.')
            else:
                conn.execute(text("INSERT INTO users(username,password_hash,role,active) VALUES(:u,:p,'admin',1) ON CONFLICT(username) DO NOTHING"),{'u':args.admin_user,'p':generate_password_hash(password)})
        print('Migration completed. Row counts:')
        with dst.connect() as conn:
            for table in TABLES: print(f'  {table}: {conn.execute(text(f"SELECT COUNT(*) FROM {table}")).scalar_one()}')
            print(f'  users: {conn.execute(text("SELECT COUNT(*) FROM users")).scalar_one()}')
        print('Original SQLite file was not modified.')
    finally:
        src.close(); dst.dispose()

if __name__=='__main__': main()
